    from collections import Counter

    bg = Counter(x for row in g for x in row).most_common(1)[0][0]
    counts = Counter(x for row in g for x in row if x != bg)
    color = counts.most_common(1)[0][0]
    pts = [(r, c) for r, row in enumerate(g) for c, x in enumerate(row) if x == color]
    other = [(r, c) for r, row in enumerate(g) for c, x in enumerate(row) if x not in (bg, color)]
    h, w = len(g), len(g[0])

    # Find the longest diagonal sequence of the principal color.
    best = None
    for dr, dc in ((1, 1), (1, -1)):
        for r, c in pts:
            if (r - dr, c - dc) in pts:
                continue
            seq = []
            rr, cc = r, c
            while (rr, cc) in pts:
                seq.append((rr, cc))
                rr += dr
                cc += dc
