        # Grow from the end farther from the other colored marks.
        def distance(p):
            if not other:
                return 0
            return min(abs(p[0] - q[0]) + abs(p[1] - q[1]) for q in other)

        if distance(seq[0]) < distance(seq[-1]):
            r, c = seq[-1]
            dr, dc = -dr, -dc
