    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while (0 <= rr < h and 0 <= cc < w
                       and grid[rr][cc] == color):
                    run.append((rr, cc))
                    rr += dr
                    cc += dc

                if len(run) < 2:
                    continue

                for (er, ec), sr, sc in ((run[0], -dr, -dc),
                                         (run[-1], dr, dc)):
                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] not in (bg, color):
                            break
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
